UPDATE datasets SET validated=1 WHERE id='8329fc51214bfc0b' AND (SELECT COUNT(*) FROM employees WHERE dataset_id='8329fc51214bfc0b')=174 AND (SELECT COUNT(*) FROM courses WHERE dataset_id='8329fc51214bfc0b')=10 AND (SELECT COUNT(*) FROM completions WHERE dataset_id='8329fc51214bfc0b')=2860 AND (SELECT COUNT(*) FROM sessions WHERE dataset_id='8329fc51214bfc0b')=34 AND (SELECT COUNT(*) FROM audit WHERE dataset_id='8329fc51214bfc0b')=4433;
INSERT INTO active_dataset(singleton,dataset_id) SELECT 1,id FROM datasets WHERE id='8329fc51214bfc0b' AND validated=1 ON CONFLICT(singleton) DO UPDATE SET dataset_id=excluded.dataset_id;
